function merge(saved){const next=structuredClone(base);Object.keys(next).forEach(k=>{if(saved?.[k]!==undefined)next[k]=saved[k]});next.version=2;return next}
function load(){try{const v=JSON.parse(localStorage.getItem(STORE)||'null');if(v)return merge(v)}catch{}try{const old=JSON.parse(localStorage.getItem(LEGACY_STORE)||'null');if(old){const n=structuredClone(base);['trucks','drivers','trips','diesel','expenses','maintenance','permits','invoices','routes'].forEach(k=>{if(old[k]?.length)n[k]=old[k]});return n}}catch{}return structuredClone(base)}
let db=load(),page='command',role=localStorage.getItem('angermund_role')||'admin',formType='';
const get=(k,id)=>(db[k]||[]).find(x=>x.id===id)||{},name=(k,id,f='name')=>get(k,id)[f]||'—',truck=id=>name('trucks',id,'registration'),driver=id=>name('drivers',id),client=id=>name('clients',id),route=id=>name('routes',id),trailer=id=>name('trailers',id,'registration');
const sum=(rows,fn)=>rows.reduce((a,x)=>a+num(fn(x)),0),linked=(k,f,id)=>(db[k]||[]).filter(x=>x[f]===id),tripCost=t=>num(t.dieselCost)+num(t.tolls)+num(t.allowance)+num(t.other),tripProfit=t=>num(t.income)-tripCost(t);
function roleLabel(){return {admin:'Admin & Operations',dispatcher:'Dispatcher',driver:'Driver',workshop:'Workshop',finance:'Finance'}[role]||role}
function commit(msg,type='system',id=''){db.audit.unshift({id:uid('log'),at:new Date().toISOString(),actor:roleLabel(),action:msg,linkedType:type,linkedId:id});db.audit=db.audit.slice(0,100);localStorage.setItem(STORE,JSON.stringify(db));render();notify(msg)}
function fuelEfficiency(id){const t=get('trips',id),litres=sum(linked('diesel','tripId',id),x=>x.litres);return litres?num(t.distance)/litres:0}
function incentiveFor(t){const e=fuelEfficiency(t.id);if(get('routes',t.routeId).crossBorder)return num(t.distance)*.60;if(e>=2.4)return num(t.distance)*.50;if(e>=2.3)return num(t.distance)*.40;if(e<2)return num(t.distance)*.30;return 0}
const currentDriver=()=>db.settings.currentDriver||db.drivers[0]?.id;
const navGroups=[['Operate',[['command','⌂','Command Centre'],['dispatch','⇄','Dispatch Board'],['trips','↗','Trips & Loads'],['driverPortal','◉','Driver Workspace'],['tasks','✓','Tasks & Approvals']]],['Fleet',[['fleet','▣','Fleet & GPS'],['inspections','☑','Inspections'],['diesel','◉','Diesel Control'],['workshop','⚙','Workshop & Service'],['tyres','◎','Tyre Register'],['documents','▤','Documents & Permits'],['incidents','!','Incidents & Discipline']]],['Business',[['clients','♧','Clients & Routes'],['invoices','▥','Invoices & Debtors'],['payroll','$','Payroll & Advances'],['rates','⌁','Rates & Quotations'],['reports','▥','Reports & P&L']]],['System',[['automation','✦','Smart Inbox'],['knowledge','?','Roles & Requirements'],['settings','⚙','Settings & Data']]]];
const allowed={driver:['driverPortal','knowledge'],workshop:['command','fleet','inspections','diesel','workshop','tyres','documents','tasks','knowledge'],finance:['command','trips','clients','invoices','payroll','rates','reports','tasks','settings'],dispatcher:['command','dispatch','trips','driverPortal','fleet','inspections','diesel','documents','incidents','clients','tasks','automation','knowledge']};
const canView=id=>role==='admin'||(allowed[role]||[]).includes(id),go=p=>{page=canView(p)?p:(role==='driver'?'driverPortal':'command');$('sidebar').classList.remove('open');render()};
const hints={command:'Live company risks, movement and financial health',dispatch:'Control every load from booking to invoice',trips:'One source of truth for loads, costs, proof and profit',driverPortal:'Assigned work, safety checks, proof and requirements',tasks:'Work queue, approvals and overdue actions',fleet:'Availability, GPS, utilization and compliance',inspections:'Pre-trip, post-trip and defect control',diesel:'Every litre linked to truck, driver and trip',workshop:'Maintenance planning, defects and service costs',tyres:'Tyre life, position, cost and replacement',documents:'Company, driver, vehicle and border compliance',incidents:'Safety, damage, warnings and corrective actions',clients:'Customers, contacts and standard routes',invoices:'Trip-to-invoice control and debtors',payroll:'Advances, incentives and payroll preparation',rates:'Diesel-linked quotes and standing charges',reports:'Linked operational and financial performance',automation:'Verify scans before records are created',knowledge:'Duties, policies and checklists by role',settings:'Defaults, roles and data protection'};
function renderNav(){$('nav').innerHTML=navGroups.map(([g,items])=>{const v=items.filter(x=>canView(x[0]));return v.length?`<div class="nav-section">${g}</div>${v.map(([id,icon,label])=>`<button data-page="${id}" class="${page===id?'active':''}"><span>${icon}</span>${label}</button>`).join('')}`:''}).join('');$('nav').querySelectorAll('button').forEach(b=>b.onclick=()=>go(b.dataset.page))}
function render(){if(!canView(page))page=role==='driver'?'driverPortal':'command';renderNav();$('pageTitle').textContent={command:'Command Centre',driverPortal:'Driver Workspace',automation:'Smart Document Inbox',knowledge:'Roles & Requirements'}[page]||navGroups.flatMap(x=>x[1]).find(x=>x[0]===page)?.[2]||'Operations';$('pageHint').textContent=hints[page]||'';$('roleSelect').value=role;$('quickTripBtn').style.display=['driver','workshop'].includes(role)?'none':'';$('app').innerHTML=(views[page]||views.command)();wire()}
const kpi=(l,v,s='',tone='')=>`<div class="kpi"><span>${l}</span><strong class="${tone}">${v}</strong><small>${s}</small></div>`;
function badge(v){const w=/pending|planned|due|expir|unpaid|part|medium|in transit|open/i.test(v),b=/overdue|failed|critical|out of service|rejected/i.test(v);return `<span class="badge ${b?'negative':w?'warn':''}">${esc(v)}</span>`}
function complianceAlerts(){const out=[];db.permits.forEach(p=>{const d=daysUntil(p.expiry);if(d<45)out.push({text:`${p.type} for ${p.ownerType==='truck'?truck(p.ownerId):driver(p.ownerId)} ${d<0?'expired':`expires in ${d} days`}`,tone:d<0?'bad':'warn'})});db.drivers.forEach(x=>{const d=daysUntil(x.prdpExpiry);if(d<45)out.push({text:`PrDP for ${x.name} ${d<0?'expired':`expires in ${d} days`}`,tone:d<0?'bad':'warn'})});return out}
const serviceDue=()=>db.trucks.filter(t=>num(t.serviceDue)-num(t.odometer)<=5000);
function command(){const active=db.trips.filter(t=>!['Delivered','Invoiced','Closed'].includes(t.status)),revenue=sum(db.trips,t=>t.income),costs=sum(db.trips,tripCost)+sum(db.expenses,x=>x.amount)+sum(db.maintenance,x=>x.cost),profit=revenue-costs,alerts=complianceAlerts(),defects=db.inspections.filter(i=>i.status==='Failed'||i.defects).length;return `<section class="hero"><div><h2>Good day, ${esc(roleLabel())}</h2><p>Dispatch, trucks, drivers, diesel, proof, invoices and costs share one linked record. Management sees exceptions—not duplicate capture.</p></div><div class="hero-actions"><button class="primary action" data-action="newTrip">Dispatch load</button><button class="ghost nav-to" data-page="tasks">Review work queue</button></div></section><section class="kpis">${kpi('Active movements',active.length,'Namibia & South Africa')}${kpi('Fleet available',db.trucks.filter(t=>t.status==='Available').length,`${db.trucks.length} units registered`)}${kpi('Compliance risks',alerts.length,`${defects} inspection defects`,alerts.length?'warning':'')}${role==='workshop'?kpi('Services due',serviceDue().length,'Within 5,000 km'):kpi('Net contribution',money(profit),`${revenue?((profit/revenue)*100).toFixed(1):0}% margin`,profit<0?'negative':'positive')}</section><section class="grid-2"><div class="panel"><div class="panel-head"><h2>Live trip control</h2><button class="small nav-to" data-page="dispatch">Open board</button></div>${tripTable(db.trips.slice(0,6))}</div><div class="panel"><h2>Requires attention</h2><div class="alerts">${[...alerts.slice(0,4),...db.tasks.filter(t=>t.status==='Open').slice(0,3).map(t=>({text:t.title,tone:t.priority==='High'?'bad':'warn'}))].map(a=>`<div class="alert"><span class="status-dot ${a.tone}"></span>${esc(a.text)}</div>`).join('')||'<div class="empty">No urgent alerts</div>'}</div></div></section><section class="panel" style="margin-top:18px"><h2>Operational pulse</h2><div class="quick-grid"><div class="quick-card"><b>GPS & security</b><p>${db.trucks.filter(t=>t.gps==='Online').length}/${db.trucks.length} vehicles reporting</p></div><div class="quick-card"><b>Diesel control</b><p>${db.diesel.filter(x=>!x.verified).length} slips awaiting verification</p></div><div class="quick-card"><b>POD control</b><p>${db.trips.filter(t=>t.stage>=4&&!t.pod).length} delivered loads missing proof</p></div><div class="quick-card"><b>Approvals</b><p>${db.approvals.filter(a=>a.status==='Pending').length} decisions pending</p></div></div></section>`}
function tripTable(rows){const fin=!['driver','workshop'].includes(role);return `<div class="table-wrap"><table><thead><tr><th>Trip</th><th>Status</th><th>Route</th><th>Truck / Driver</th><th>Load</th>${fin?'<th>Income</th><th>Profit</th>':''}<th>Proof</th><th></th></tr></thead><tbody>${rows.length?rows.map(t=>`<tr><td><b>${esc(t.number)}</b><br><small>${esc(t.date)}</small></td><td>${badge(t.status)}</td><td>${esc(route(t.routeId))}<br><small>${num(t.distance).toLocaleString()} km</small></td><td>${esc(truck(t.truckId))}<br><small>${esc(driver(t.driverId))}</small></td><td>${esc(t.load||'—')}</td>${fin?`<td>${money(t.income)}</td><td class="${tripProfit(t)>=0?'positive':'negative'}">${money(tripProfit(t))}</td>`:''}<td>${t.pod?'✓ POD':'Missing'}</td><td><button class="link-button open-trip" data-id="${t.id}">Open</button></td></tr>`).join(''):'<tr><td colspan="9" class="empty">No trips recorded</td></tr>'}</tbody></table></div>`}
function dispatch(){const cols=[['Planned',1],['Loading',2],['In transit',3],['Delivered',4],['Invoiced',5]];return `<div class="notice">Advance each load through one controlled workflow. Vehicle and driver status update from this trip record.</div><div class="workflow">${cols.map(([l,s])=>`<div class="stage ${s<3?'done':s===3?'current':''}"><span>Stage ${s}</span><strong>${l}</strong><p>${db.trips.filter(t=>num(t.stage)===s).length} load(s)</p></div>`).join('')}</div><div class="cards-list">${db.trips.map(tripCard).join('')}</div>`}
function tripCard(t){const next={1:'Start loading',2:'Depart',3:'Confirm delivery',4:'Create invoice',5:'Close'}[t.stage]||'Open';return `<article class="entity-card"><div class="panel-head"><h3>${esc(t.number)}</h3>${badge(t.status)}</div><p><b>${esc(route(t.routeId))}</b></p><p>${esc(client(t.clientId))} · ${esc(t.load)}</p><p>${esc(truck(t.truckId))} / ${esc(driver(t.driverId))}</p><div class="progress"><i style="width:${Math.min(100,num(t.stage)*20)}%"></i></div><div class="metric-line"><span>Contribution</span><b class="${tripProfit(t)>=0?'positive':'negative'}">${money(tripProfit(t))}</b></div><button class="primary small advance-trip" data-id="${t.id}">${next}</button> <button class="ghost small open-trip" data-id="${t.id}">Details</button></article>`}
function trips(){return `<div class="panel"><div class="toolbar"><input id="tripSearch" placeholder="Search trip, route, client, truck or driver"><div><button class="ghost export" data-kind="trips">Export</button> <button class="primary action" data-action="newTrip">+ New trip</button></div></div><div id="tripResults">${tripTable(db.trips)}</div></div>`}
function driverPortal(){const did=currentDriver(),d=get('drivers',did),mine=db.trips.filter(t=>t.driverId===did&&!['Closed','Invoiced'].includes(t.status)),tasks=db.tasks.filter(t=>t.ownerRole==='Driver'&&t.status==='Open'),t=mine[0];return `<div class="notice red"><b>Zero tolerance:</b> No passengers, friends, family or hitchhikers in any company truck. A violation may lead to immediate dismissal. The driver is responsible for unauthorized-passenger accident claims.</div><section class="hero"><div><h2>${esc(d.name||'Driver')} · ${esc(d.role||'Driver')}</h2><p>Driver score ${num(d.score)}/100 · PrDP ${esc(d.prdpExpiry)} · ${mine.length} active assignment(s)</p></div><div class="hero-actions"><button class="primary action" data-action="checkIn">GPS check-in</button><button class="ghost action" data-action="incident">Report incident</button></div></section>${t?`<section class="panel"><div class="panel-head"><h2>Current assignment · ${esc(t.number)}</h2>${badge(t.status)}</div><div class="split-3"><div><span>Route</span><h3>${esc(route(t.routeId))}</h3><p>${esc(client(t.clientId))}</p></div><div><span>Vehicle</span><h3>${esc(truck(t.truckId))}</h3><p>${esc(trailer(t.trailerId))}</p></div><div><span>Load</span><h3>${esc(t.load)}</h3><p>${num(t.tons)} tons · ${num(t.pallets)} pallets</p></div></div><div class="workflow">${['Accept','Inspect & load','Travel','Deliver & POD','Close'].map((x,i)=>`<div class="stage ${t.stage>i+1?'done':t.stage===i+1?'current':''}"><span>${i+1}</span><strong>${x}</strong></div>`).join('')}</div><div class="hero-actions"><button class="primary action" data-action="inspection" data-trip="${t.id}">Pre-trip inspection</button><button class="ghost action" data-action="diesel" data-trip="${t.id}">Capture diesel slip</button><button class="ghost action" data-action="pod" data-trip="${t.id}">Upload POD</button></div></section>`:'<div class="panel empty">No active assignment. Contact dispatch if this is incorrect.</div>'}<section class="grid-2" style="margin-top:18px"><div class="panel"><h2>My required actions</h2>${tasks.length?tasks.map(x=>`<div class="check-row"><input type="checkbox" class="complete-task" data-id="${x.id}"><label><b>${esc(x.title)}</b><small>Due ${esc(x.due)} · ${esc(x.priority)} priority</small></label></div>`).join(''):'<div class="empty">All driver tasks completed</div>'}</div><div class="panel"><h2>Trip reminders</h2><div class="policy"><h3>Before departure</h3><p>Inspect vehicle, confirm documents, load security, route and contacts.</p></div><div class="policy"><h3>During trip</h3><p>Use approved route, preserve receipts, report delays and never carry unauthorized passengers.</p></div><div class="policy"><h3>At delivery</h3><p>Confirm quantities, obtain signed POD and report damage or shortage immediately.</p></div></div></section>`}
function fleet(){return `<section class="kpis">${kpi('Available',db.trucks.filter(t=>t.status==='Available').length,'Ready for dispatch')}${kpi('On work',db.trucks.filter(t=>/trip|duty/i.test(t.status)).length,'Currently allocated')}${kpi('GPS online',db.trucks.filter(t=>t.gps==='Online').length,`${db.trucks.length} registered`)}${kpi('Service due',serviceDue().length,'Within 5,000 km')}</section><div class="cards-list">${db.trucks.map(t=>`<article class="entity-card"><div class="panel-head"><h3>${esc(t.registration)}</h3>${badge(t.status)}</div><p>${esc(t.make)} · ${esc(t.type)}</p><p><span class="status-dot ${t.gps==='Online'?'':'bad'}"></span>GPS ${esc(t.gps)}</p><div class="metric-line"><span>Odometer</span><b>${num(t.odometer).toLocaleString()} km</b></div><div class="metric-line"><span>Next service</span><b>${num(t.serviceDue).toLocaleString()} km</b></div><div class="metric-line"><span>Trips</span><b>${db.trips.filter(x=>x.truckId===t.id).length}</b></div></article>`).join('')}</div>`}
function diesel(){const litres=sum(db.diesel,x=>x.litres),spend=sum(db.diesel,x=>num(x.litres)*num(x.price));return `<section class="kpis">${kpi('Fuel spend',money(spend),'Verified and pending')}${kpi('Litres',litres.toLocaleString()+' L',`${db.diesel.length} entries`)}${kpi('Average price',money(litres?spend/litres:0),'Per litre')}${kpi('Below target',db.trips.filter(t=>fuelEfficiency(t.id)&&fuelEfficiency(t.id)<db.settings.targetKml).length,`Target ${db.settings.targetKml} km/L`,'warning')}</section>${dataTable('Diesel entries','diesel',['Date','Trip','Truck','Driver','Litres','Price','Efficiency','Status'],db.diesel,x=>[x.date,get('trips',x.tripId).number||'—',truck(x.truckId),driver(x.driverId),`${num(x.litres).toLocaleString()} L`,money(x.price),x.tripId?`${fuelEfficiency(x.tripId).toFixed(2)} km/L`:'—',x.verified?'Verified':'Review'])}`}
function inspections(){return `<div class="panel"><div class="toolbar"><h2>Safety inspections & defects</h2><button class="primary add-record" data-type="inspection">+ Start inspection</button></div>${table(['Date','Type','Vehicle','Driver','Trip','Score','Defects','Status'],db.inspections,x=>[x.date,x.type,truck(x.truckId),driver(x.driverId),get('trips',x.tripId).number||'—',`${num(x.score)}%`,x.defects||'None',x.status])}</div>`}
function workshop(){return `<section class="kpis">${kpi('Open work orders',db.maintenance.filter(x=>x.status!=='Completed').length,'Workshop queue')}${kpi('Service due',serviceDue().length,'Within 5,000 km')}${kpi('Maintenance spend',money(sum(db.maintenance,x=>x.cost)),'Linked to vehicles')}${kpi('Inspection defects',db.inspections.filter(x=>x.defects).length,'Needs review')}</section>${dataTable('Maintenance & service','maintenance',['Date','Vehicle','Work','Supplier','Odometer','Cost','Next service','Status'],db.maintenance,x=>[x.date,truck(x.truckId),x.type,x.supplier,num(x.odometer).toLocaleString(),money(x.cost),num(x.nextService).toLocaleString(),x.status])}`}
function tyres(){return dataTable('Tyre register','tyre',['Serial','Vehicle','Position','Brand','Fitted KM','Current KM','Life used','Cost','Status'],db.tyres,x=>[x.serial,truck(x.truckId),x.position,x.brand,num(x.fittedKm).toLocaleString(),num(x.currentKm).toLocaleString(),`${Math.max(0,num(x.currentKm)-num(x.fittedKm)).toLocaleString()} km`,money(x.cost),x.status])}
function documents(){const a=complianceAlerts();return `<div class="notice ${a.length?'red':''}">${a.length?`<b>${a.length} compliance item(s) need action.</b> Do not dispatch expired drivers or vehicles.`:'All captured documents are valid.'}</div><div class="panel"><div class="toolbar"><h2>Compliance register</h2><button class="primary add-record" data-type="permit">+ Add document</button></div>${table(['Document','Owner','Reference','Issued','Expiry','Days left','Status'],db.permits,x=>[x.type,x.ownerType==='truck'?truck(x.ownerId):driver(x.ownerId),x.reference,x.issued,x.expiry,daysUntil(x.expiry),daysUntil(x.expiry)<0?'Expired':daysUntil(x.expiry)<45?'Expiring':'Valid'])}</div><section class="panel" style="margin-top:18px"><h2>Cross-border trip pack</h2><div class="doc-grid">${['Company authorization letter','Truck registration certificate','Trailer registration certificate','Vehicle licence disk','Roadworthy certificate','Insurance proof','Driver licence & PrDP','Passport','SARS TMS reference','Temporary Import Permit (TIP)','Waybill / manifest','Invoice & delivery note'].map(d=>`<div class="doc-card"><span class="doc-icon">▤</span><h3>${d}</h3><p>Required where applicable before Namibia–South Africa departure.</p></div>`).join('')}</div></section>`}
function incidents(){return `<div class="panel"><div class="toolbar"><h2>Incidents, damage & discipline</h2><button class="primary add-record" data-type="incident">+ Report incident</button></div>${table(['Date','Type','Vehicle','Driver','Severity','Description','Status','Action'],db.incidents,x=>[x.date,x.type,truck(x.truckId),driver(x.driverId),x.severity,x.description,x.status,x.action])}</div><section class="grid-2" style="margin-top:18px"><div class="panel"><h2>Progressive discipline workflow</h2><div class="timeline"><div class="timeline-item"><b>Record facts & evidence</b><small>Employee, date, place, witnesses, photos and linked asset/trip.</small></div><div class="timeline-item"><b>Request written explanation</b><small>Allow response; do not pre-judge.</small></div><div class="timeline-item"><b>Manager review</b><small>Coaching, warning, final warning or hearing.</small></div><div class="timeline-item"><b>Acknowledge & follow up</b><small>Signatures, validity and corrective action.</small></div></div></div><div class="panel"><h2>Key controls</h2><div class="policy critical"><h3>Unauthorized passengers</h3><p>Zero tolerance under the NBL directive.</p></div><div class="policy"><h3>Unauthorized equipment use</h3><p>Capture damage, approval status and signed lawful repayment terms.</p></div><div class="policy"><h3>Attendance / no-show</h3><p>Capture duty, notification, explanation and progressive action.</p></div></div></section>`}
function clients(){return `<section class="grid-2"><div class="panel"><div class="toolbar"><h2>Clients</h2><button class="primary add-record" data-type="client">+ Client</button></div>${table(['Client','Terms','Contact','Status','Trips','Revenue'],db.clients,x=>[x.name,`${num(x.terms)} days`,x.contact,x.status,db.trips.filter(t=>t.clientId===x.id).length,money(sum(db.trips.filter(t=>t.clientId===x.id),t=>t.income))])}</div><div class="panel"><div class="toolbar"><h2>Standard routes</h2><button class="primary add-record" data-type="route">+ Route</button></div>${table(['Route','Distance','Standard rate','Type'],db.routes,x=>[x.name,`${num(x.distance).toLocaleString()} km`,money(x.rate),x.crossBorder?'Cross-border':'Namibia'])}</div></section>`}
function invoices(){const out=db.invoices.filter(i=>i.status!=='Paid');return `<section class="kpis">${kpi('Invoiced',money(sum(db.invoices,x=>x.amount)),'Total issued')}${kpi('Outstanding',money(sum(out,x=>x.amount)),`${out.length} invoice(s)`)}${kpi('Uninvoiced deliveries',db.trips.filter(t=>t.stage>=4&&!t.invoiceId).length,'Revenue at risk','warning')}${kpi('Average terms',`${Math.round(sum(db.clients,x=>x.terms)/Math.max(1,db.clients.length))} days`,'Customer terms')}</section>${dataTable('Invoices & debtors','invoice',['Invoice','Date','Client','Trip','Amount','Due','Status'],db.invoices,x=>[x.number,x.date,client(x.clientId),get('trips',x.tripId).number||'—',money(x.amount),x.due,x.status])}`}
function payroll(){const ins=db.trips.filter(t=>t.stage>=4).map(t=>({trip:t.number,driver:driver(t.driverId),eff:fuelEfficiency(t.id),amount:incentiveFor(t)}));return `<section class="grid-2"><div class="panel"><h2>Driver incentive rules</h2><div class="metric-line"><span>Under 2.0 km/L</span><b>N$0.30/km</b></div><div class="metric-line"><span>2.3 km/L</span><b>N$0.40/km</b></div><div class="metric-line"><span>2.4+ km/L</span><b>N$0.50/km</b></div><div class="metric-line"><span>South Africa</span><b>N$0.60/km</b></div></div><div class="panel"><h2>Calculated incentives</h2>${table(['Trip','Driver','Efficiency','Incentive'],ins,x=>[x.trip,x.driver,`${x.eff.toFixed(2)} km/L`,money(x.amount)])}</div></section><section class="grid-2" style="margin-top:18px">${dataTable('Driver advances','advance',['Date','Driver','Trip','Type','Amount','Status'],db.advances,x=>[x.date,driver(x.driverId),get('trips',x.tripId).number||'—',x.type,money(x.amount),x.status])}${dataTable('Payroll','payroll',['Period','Employee','Days','OT','Base','Incentive','Deductions','Net','Status'],db.payroll,x=>[x.period,driver(x.employeeId),x.days,x.overtime,money(x.base),money(x.incentive),money(x.deductions),money(num(x.base)+num(x.incentive)-num(x.deductions)),x.status])}</section>`}
function tasks(){return `<section class="grid-2"><div class="panel"><h2>Work queue</h2>${db.tasks.map(t=>`<div class="approval"><div><b>${esc(t.title)}</b><small style="display:block;color:var(--muted)">${esc(t.ownerRole)} · due ${esc(t.due)} · ${esc(t.priority)}</small></div><div>${badge(t.status)} ${t.status==='Open'?`<button class="small complete-task" data-id="${t.id}">Complete</button>`:''}</div></div>`).join('')}</div><div class="panel"><h2>Approvals</h2>${db.approvals.map(a=>`<div class="approval"><div><b>${esc(a.description)}</b><small style="display:block;color:var(--muted)">${esc(a.type)} · ${esc(a.requester)} · ${money(a.amount)}</small></div><div>${badge(a.status)} ${a.status==='Pending'?`<button class="small approval-action" data-id="${a.id}" data-status="Approved">Approve</button> <button class="danger small approval-action" data-id="${a.id}" data-status="Rejected">Reject</button>`:''}</div></div>`).join('')}</div></section>`}
function rates(){return `<section class="grid-2"><div class="panel"><h2>Diesel-linked quotation</h2><div class="form-grid" id="rateForm"><div class="field"><label>Route</label><select id="rcRoute">${db.routes.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></div>${[['rcDistance','Total distance (km)',db.routes[0]?.distance||0,1],['rcKml','Expected km/L',2,.1],['rcDiesel','Diesel price/L',db.settings.dieselPrice,.01],['rcDriver','Driver / allowances',600,1],['rcTolls','Tolls / border / permits',0,1],['rcWear','Tyres & maintenance provision',3500,1],['rcOther','Other / overhead',1500,1],['rcMargin','Profit margin (%)',db.settings.defaultMargin,1],['rcWaiting','Waiting days',0,1]].map(x=>`<div class="field"><label>${x[1]}</label><input id="${x[0]}" type="number" value="${x[2]}" step="${x[3]}"></div>`).join('')}</div></div><div class="panel"><h2>Recommended quotation</h2><div id="rateResult"></div><button class="primary" id="saveQuote">Save quotation task</button></div></section><section class="panel" style="margin-top:18px"><h2>Standing / detention</h2><p>${db.settings.freeStandingHours} free offloading hours, then <b>${money(db.settings.standingFee)}</b> per commenced 24 hours excluding VAT. Weekend/public holiday guide: <b>${money(db.settings.weekendStandingFee)}</b>.</p></section>`}
function reports(){const rev=sum(db.trips,t=>t.income),cost=sum(db.trips,tripCost)+sum(db.expenses,x=>x.amount)+sum(db.maintenance,x=>x.cost),profit=rev-cost,rows=db.trucks.map(t=>{const a=db.trips.filter(x=>x.truckId===t.id);return{name:t.registration,trips:a.length,revenue:sum(a,x=>x.income),profit:sum(a,tripProfit)}});return `<section class="kpis">${kpi('Revenue',money(rev),'All trips')}${kpi('Operating cost',money(cost),'Linked records')}${kpi('Net contribution',money(profit),`${rev?((profit/rev)*100).toFixed(1):0}%`,profit>=0?'positive':'negative')}${kpi('Distance',`${sum(db.trips,t=>t.distance).toLocaleString()} km`,'All trips')}</section><div class="panel"><h2>Vehicle performance</h2>${table(['Vehicle','Trips','Revenue','Contribution','Revenue / trip'],rows,x=>[x.name,x.trips,money(x.revenue),money(x.profit),money(x.trips?x.revenue/x.trips:0)])}</div><section class="grid-2" style="margin-top:18px"><div class="panel"><h2>Driver performance</h2>${db.drivers.map(d=>`<div class="metric-line"><span>${esc(d.name)}</span><b>${num(d.score)}/100</b></div>`).join('')}</div><div class="panel"><h2>Audit trail</h2>${db.audit.slice(0,8).map(a=>`<div class="timeline-item"><b>${esc(a.action)}</b><small>${new Date(a.at).toLocaleString()} · ${esc(a.actor)}</small></div>`).join('')}</div></section>`}
function automation(){return `<div class="notice"><b>Human verification is mandatory.</b> Scans may suggest links, but unclear amounts are never posted automatically.</div><section class="split-3"><div class="panel"><h2>1 · Capture</h2><div class="doc-grid">${[['▤','Diesel slip','Supplier, litres, amount, truck and odometer'],['✓','POD / delivery note','Link signed proof to the trip'],['$','Invoice / receipt','Suggest client, trip and category']].map(x=>`<div class="doc-card action" data-action="scan"><span class="doc-icon">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div></div><div class="panel"><h2>2 · Review</h2><div class="policy"><h3>No silent entries</h3><p>Low-confidence amounts remain blank.</p></div><div class="policy"><h3>No duplicates</h3><p>Number, date, supplier and amount are compared.</p></div></div><div class="panel"><h2>3 · Connected result</h2><p>Approval updates the trip, truck, driver, cost, invoice and dashboard.</p><div class="metric-line"><span>Awaiting review</span><b>0</b></div><div class="metric-line"><span>Possible duplicates</span><b>0</b></div></div></section>`}
function knowledge(){return `<section class="grid-2"><div class="panel"><h2>Driver role & requirements</h2><div class="policy critical"><h3>No passengers or hitchhikers</h3><p>No friends, family, passengers or hitchhikers. A violation may result in immediate dismissal.</p></div><div class="policy"><h3>Before every trip</h3><p>Be fit for duty; valid licence/PrDP and border documents; inspect tyres, lights, brakes, fluids and load security.</p></div><div class="policy"><h3>During every trip</h3><p>Protect cargo; obey traffic/site rules; never use equipment without authorization; report delays, damage and incidents.</p></div><div class="policy"><h3>At delivery</h3><p>Check condition, obtain signed POD, photograph proof, capture end odometer and return receipts/advance.</p></div></div><div class="panel"><h2>Office & dispatcher role</h2><div class="policy"><h3>Safe dispatch</h3><p>Confirm valid driver, truck, trailer, route, load, customer instruction and documents.</p></div><div class="policy"><h3>Live control</h3><p>Monitor GPS, milestones, speeding/security, check-ins and delays.</p></div><div class="policy"><h3>Financial closure</h3><p>Match diesel, tolls, advances, POD and rate; verify profit; invoice and follow payment.</p></div><div class="policy"><h3>Record integrity</h3><p>Use master data, prevent duplicates and never approve unclear scan amounts.</p></div></div></section><section class="split-3" style="margin-top:18px"><div class="panel"><h2>Workshop</h2><p>Review defects, record parts/labour, update odometer and verify roadworthiness.</p></div><div class="panel"><h2>Finance</h2><p>Reconcile costs, advances, invoices, standing fees, payroll/PAYE and evidence.</p></div><div class="panel"><h2>Management</h2><p>Review exceptions, profit, fuel, safety, debtors, approvals and audit history.</p></div></section>`}
function settings(){const input=(l,id,v)=>`<div class="field" style="margin-bottom:12px"><label>${l}</label><input id="${id}" type="number" step="any" value="${v}"></div>`;return `<section class="settings-grid"><div class="panel"><h2>Operating defaults</h2>${input('Diesel price / litre','setDiesel',db.settings.dieselPrice)}${input('VAT %','setVat',db.settings.vat)}${input('Fuel warning km/L','setKml',db.settings.targetKml)}${input('Standing fee / day','setStanding',db.settings.standingFee)}<button class="primary" id="saveSettings">Save defaults</button></div><div class="panel"><h2>Driver device</h2><div class="field"><label>Driver using this device</label><select id="setDriver">${db.drivers.map(d=>`<option value="${d.id}" ${d.id===currentDriver()?'selected':''}>${esc(d.name)}</option>`).join('')}</select></div><br><button class="primary" id="saveDriver">Save driver</button></div><div class="panel"><h2>Data protection</h2><p>Backup includes linked records, rules and audit history.</p><button class="primary" id="downloadBackup">Download backup</button><br><br><button class="ghost" id="restoreBackup">Restore backup</button><br><br><button class="danger" id="resetData">Reset demonstration data</button></div></section>`}
function dataTable(title,type,heads,rows,map){return `<div class="panel"><div class="toolbar"><h2>${title}</h2><div><button class="ghost export" data-kind="${type}">Export</button> <button class="primary add-record" data-type="${type}">+ Add</button></div></div>${table(heads,rows,map)}</div>`}
function table(heads,rows,map){return `<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${map(r).map(v=>`<td>${typeof v==='string'&&/^(Active|Available|Completed|Passed|Verified|Valid|Paid|Pending|Open|Expired|Expiring|Unpaid|Review|Medium)$/.test(v)?badge(v):esc(v??'—')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}" class="empty">No records yet</td></tr>`}</tbody></table></div>`}
const views={command,dispatch,trips,driverPortal,tasks,fleet,inspections,diesel,workshop,tyres,documents,incidents,clients,invoices,payroll,rates,reports,automation,knowledge,settings};
const forms={trip:[['date','Date','date',today()],['routeId','Route','route'],['clientId','Client','client'],['truckId','Truck','truck'],['trailerId','Trailer','trailer'],['driverId','Driver','driver'],['load','Load description','text',''],['tons','Tons','number',0],['pallets','Pallets','number',0],['startKm','Start odometer','number',0],['income','Agreed rate','number',0],['status','Status','select','Planned',['Planned','Loading','In transit','Delivered']]],diesel:[['date','Date','date',today()],['tripId','Trip','trip'],['truckId','Truck','truck'],['driverId','Driver','driver'],['litres','Litres','number',0],['price','Price / litre','number',26.77],['odometer','Odometer','number',0],['supplier','Supplier','text',''],['slip','Slip number','text','']],inspection:[['date','Date','date',today()],['tripId','Trip','trip'],['truckId','Truck','truck'],['driverId','Driver','driver'],['type','Inspection','select','Pre-trip',['Pre-trip','Post-trip','Workshop']],['defects','Defects / notes','textarea','']],incident:[['date','Date','date',today()],['type','Incident type','select','Vehicle damage',['Accident','Vehicle damage','Cargo damage','Property damage','Safety breach','Unauthorized use','Attendance / no-show']],['tripId','Trip','trip'],['truckId','Truck','truck'],['driverId','Driver / employee','driver'],['severity','Severity','select','Medium',['Low','Medium','High','Critical']],['description','What happened','textarea',''],['action','Immediate action','textarea','']],permit:[['type','Document type','text',''],['ownerType','Owner type','select','truck',['truck','driver']],['ownerId','Owner ID','text',''],['reference','Reference','text',''],['issued','Issued','date',today()],['expiry','Expiry','date','']],maintenance:[['date','Date','date',today()],['truckId','Vehicle','truck'],['type','Work / service','text',''],['supplier','Supplier','text',''],['odometer','Odometer','number',0],['cost','Cost','number',0],['nextService','Next service KM','number',0],['status','Status','select','Open',['Open','In progress','Completed']]],tyre:[['serial','Serial / ID','text',''],['truckId','Vehicle','truck'],['position','Position','text',''],['brand','Brand','text',''],['fittedKm','Fitted KM','number',0],['currentKm','Current KM','number',0],['cost','Cost','number',0],['status','Status','select','Good',['Good','Monitor','Replace','Removed']]],invoice:[['number','Invoice number','text',''],['date','Date','date',today()],['clientId','Client','client'],['tripId','Trip','trip'],['amount','Amount','number',0],['due','Due date','date',''],['status','Status','select','Unpaid',['Unpaid','Part Paid','Paid','Overdue']]],advance:[['date','Date','date',today()],['driverId','Driver','driver'],['tripId','Trip','trip'],['type','Type','select','Food / trip advance',['Food / trip advance','Toll advance','Border advance','Other']],['amount','Amount','number',0],['status','Status','select','Issued',['Requested','Issued','Reconciled']]],payroll:[['period','Period','month',''],['employeeId','Employee','driver'],['days','Days worked','number',0],['overtime','Overtime hours','number',0],['base','Base pay','number',0],['incentive','Incentive','number',0],['deductions','Deductions','number',0],['status','Status','select','Draft',['Draft','Approved','Paid']]],client:[['name','Client name','text',''],['terms','Payment terms','number',30],['contact','Contact','text',''],['email','Email','email',''],['status','Status','select','Active',['Active','Inactive']]],route:[['name','Route name','text',''],['distance','Distance','number',0],['rate','Standard rate','number',0],['crossBorder','Cross-border','select','false',['false','true']],['notes','Notes','textarea','']]};
function options(type){return {truck:db.trucks.map(x=>[x.id,x.registration]),trailer:db.trailers.map(x=>[x.id,x.registration]),driver:db.drivers.map(x=>[x.id,x.name]),client:db.clients.map(x=>[x.id,x.name]),route:db.routes.map(x=>[x.id,x.name]),trip:db.trips.map(x=>[x.id,`${x.number} · ${route(x.routeId)}`])}[type]||[]}
function openForm(type,prefill={}){formType=type;const list=forms[type];if(!list)return notify(`Open ${type} from its linked workflow`);$('modalTitle').textContent=`Add ${type}`;$('entryForm').innerHTML=`<div class="form-grid">${list.map(([key,label,kind,def,vals])=>{const value=prefill[key]??def??'',opts=kind==='select'?(vals||[]).map(v=>[String(v),String(v)]):options(kind);if(opts.length)return `<div class="field"><label>${label}</label><select name="${key}"><option value="">Select…</option>${opts.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;if(kind==='textarea')return `<div class="field full"><label>${label}</label><textarea name="${key}" rows="3">${esc(value)}</textarea></div>`;return `<div class="field"><label>${label}</label><input name="${key}" type="${kind}" step="any" value="${esc(value)}"></div>`}).join('')}<div class="form-actions"><button type="button" class="ghost" id="cancelForm">Cancel</button><button class="primary">Save & link record</button></div></div>`;$('modal').classList.remove('hidden');$('cancelForm').onclick=()=>$('modal').classList.add('hidden')}
function saveForm(e){e.preventDefault();const o={id:uid(formType)};new FormData($('entryForm')).forEach((v,k)=>o[k]=v);['tons','pallets','startKm','income','litres','price','odometer','cost','nextService','fittedKm','currentKm','amount','days','overtime','base','incentive','deductions','distance','rate','terms'].forEach(k=>{if(k in o)o[k]=num(o[k])});if(o.crossBorder)o.crossBorder=o.crossBorder==='true';const map={trip:'trips',diesel:'diesel',inspection:'inspections',incident:'incidents',permit:'permits',maintenance:'maintenance',tyre:'tyres',invoice:'invoices',advance:'advances',payroll:'payroll',client:'clients',route:'routes'},key=map[formType];if(formType==='trip'){o.number=`AT-${1000+db.trips.length+1}`;o.stage={Planned:1,Loading:2,'In transit':3,Delivered:4}[o.status]||1;o.distance=get('routes',o.routeId).distance||0;o.dieselCost=o.tolls=o.allowance=o.other=0;o.pod=false;o.approved=false;get('trucks',o.truckId).status='Reserved';get('drivers',o.driverId).status='Assigned'}if(formType==='diesel'){o.verified=false;const t=get('trips',o.tripId);if(t.id)t.dieselCost=sum(linked('diesel','tripId',t.id),x=>num(x.litres)*num(x.price))+num(o.litres)*num(o.price)}if(formType==='inspection'){o.items={tyres:true,lights:true,brakes:true,fluids:true,documents:true,load:true};o.score=o.defects?80:100;o.status=o.defects?'Failed':'Passed'}if(formType==='incident')o.status='Open';if(formType==='permit')o.status='Active';db[key].unshift(o);$('modal').classList.add('hidden');commit(`${formType} record created`,formType,o.id)}
function advanceTrip(id){const t=get('trips',id);if(t.stage===4&&!t.pod)return notify('Upload POD before invoicing');if(t.stage<5){t.stage++;t.status={2:'Loading',3:'In transit',4:'Delivered',5:'Invoiced'}[t.stage];if(t.stage===3){get('trucks',t.truckId).status='On trip';get('drivers',t.driverId).status='On trip'}if(t.stage===4)db.tasks.unshift({id:uid('task'),title:`Upload POD for ${t.number}`,ownerRole:'Driver',linkedType:'trip',linkedId:t.id,due:today(),priority:'High',status:'Open'});if(t.stage===5){const inv={id:uid('inv'),number:`INV-${1000+db.invoices.length+1}`,date:today(),clientId:t.clientId,tripId:t.id,amount:t.income,due:'',status:'Unpaid'};db.invoices.unshift(inv);t.invoiceId=inv.id;get('trucks',t.truckId).status='Available';get('drivers',t.driverId).status='Available'}}commit(`${t.number} moved to ${t.status}`,'trip',t.id)}
function openTrip(id){const t=get('trips',id);$('modalTitle').textContent=`${t.number} · ${route(t.routeId)}`;$('entryForm').innerHTML=`<div class="split-3"><div><h3>Assignment</h3><p>${client(t.clientId)}<br>${truck(t.truckId)} / ${trailer(t.trailerId)}<br>${driver(t.driverId)}</p></div><div><h3>Load</h3><p>${esc(t.load)}<br>${num(t.tons)} tons · ${num(t.pallets)} pallets<br>${num(t.distance)} km</p></div><div><h3>Financial</h3><p>Income ${money(t.income)}<br>Costs ${money(tripCost(t))}<br><b>Profit ${money(tripProfit(t))}</b></p></div></div><h3>Linked records</h3><div class="quick-grid"><div class="quick-card"><b>Diesel</b><p>${linked('diesel','tripId',t.id).length} slip(s)</p></div><div class="quick-card"><b>Inspections</b><p>${linked('inspections','tripId',t.id).length} completed</p></div><div class="quick-card"><b>Advances</b><p>${money(sum(linked('advances','tripId',t.id),x=>x.amount))}</p></div><div class="quick-card"><b>Invoice</b><p>${t.invoiceId?get('invoices',t.invoiceId).number:'Not created'}</p></div></div><div class="form-actions"><button type="button" class="ghost" id="cancelForm">Close</button><button type="button" class="primary" id="advanceFromModal">Advance workflow</button></div>`;$('modal').classList.remove('hidden');$('cancelForm').onclick=()=>$('modal').classList.add('hidden');$('advanceFromModal').onclick=()=>{$('modal').classList.add('hidden');advanceTrip(t.id)}}
function rateResult(){const v=id=>num($(id).value),distance=v('rcDistance'),litres=distance/Math.max(.1,v('rcKml')),diesel=litres*v('rcDiesel'),standing=v('rcWaiting')*db.settings.standingFee,cost=diesel+v('rcDriver')+v('rcTolls')+v('rcWear')+v('rcOther')+standing,margin=Math.min(90,v('rcMargin'))/100,rate=cost/(1-margin),vat=rate*db.settings.vat/100;$('rateResult').innerHTML=`<div class="metric-line"><span>Diesel required</span><b>${litres.toFixed(1)} L</b></div><div class="metric-line"><span>Diesel cost</span><b>${money(diesel)}</b></div><div class="metric-line"><span>Standing charges</span><b>${money(standing)}</b></div><div class="metric-line"><span>Total cost</span><b>${money(cost)}</b></div><div class="metric-line"><span>Rate excl. VAT</span><b class="positive">${money(rate)}</b></div><div class="metric-line"><span>VAT</span><b>${money(vat)}</b></div><div class="metric-line"><span>Quote incl. VAT</span><b>${money(rate+vat)}</b></div><div class="metric-line"><span>Expected profit</span><b>${money(rate-cost)}</b></div>`}
function download(name,data,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportCsv(kind){const key={tyre:'tyres',invoice:'invoices',advance:'advances'}[kind]||kind,rows=db[key]||[];if(!rows.length)return notify('No data to export');const keys=[...new Set(rows.flatMap(Object.keys))],csv=[keys.join(','),...rows.map(r=>keys.map(k=>`"${String(typeof r[k]==='object'?JSON.stringify(r[k]):r[k]??'').replace(/"/g,'""')}"`).join(','))].join('\n');download(`${kind}-${today()}.csv`,csv,'text/csv')}
function backup(){download(`Angermund_Transport_Operations_${today()}.json`,JSON.stringify(db,null,2))}
function restore(file){const reader=new FileReader();reader.onload=()=>{try{const n=JSON.parse(reader.result);if(!n.trips||!n.trucks)throw Error('Invalid transport backup');db=merge(n);commit('Backup restored')}catch(e){notify(e.message)}};reader.readAsText(file)}
function notify(msg){$('toast').textContent=msg;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2400)}
function wire(){document.querySelectorAll('.nav-to').forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll('.action').forEach(b=>b.onclick=()=>{const a=b.dataset.action,id=b.dataset.trip,t=get('trips',id);if(a==='newTrip')openForm('trip');else if(a==='inspection')openForm('inspection',{tripId:id,truckId:t.truckId,driverId:t.driverId});else if(a==='diesel')openForm('diesel',{tripId:id,truckId:t.truckId,driverId:t.driverId});else if(a==='incident')openForm('incident',{tripId:id});else if(a==='pod'){t.pod=true;db.tasks.filter(x=>x.linkedId===id&&/POD/.test(x.title)).forEach(x=>x.status='Completed');commit(`POD linked to ${t.number}`,'trip',id)}else if(a==='checkIn')commit(`Driver GPS check-in at ${new Date().toLocaleTimeString()}`,'driver',currentDriver());else if(a==='scan')notify('Review opened — unclear amounts require manual entry')});document.querySelectorAll('.add-record').forEach(b=>b.onclick=()=>openForm(b.dataset.type));document.querySelectorAll('.advance-trip').forEach(b=>b.onclick=()=>advanceTrip(b.dataset.id));document.querySelectorAll('.open-trip').forEach(b=>b.onclick=()=>openTrip(b.dataset.id));document.querySelectorAll('.complete-task').forEach(b=>b.onclick=()=>{get('tasks',b.dataset.id).status='Completed';commit('Task completed','task',b.dataset.id)});document.querySelectorAll('.approval-action').forEach(b=>b.onclick=()=>{get('approvals',b.dataset.id).status=b.dataset.status;commit(`Request ${b.dataset.status.toLowerCase()}`,'approval',b.dataset.id)});document.querySelectorAll('.export').forEach(b=>b.onclick=()=>exportCsv(b.dataset.kind));const s=$('tripSearch');if(s)s.oninput=()=>{$('tripResults').innerHTML=tripTable(db.trips.filter(t=>[t.number,route(t.routeId),client(t.clientId),truck(t.truckId),driver(t.driverId)].join(' ').toLowerCase().includes(s.value.toLowerCase())))};if(page==='rates'){document.querySelectorAll('#rateForm input,#rateForm select').forEach(x=>x.oninput=rateResult);$('rcRoute').onchange=()=>{$('rcDistance').value=get('routes',$('rcRoute').value).distance;rateResult()};rateResult();$('saveQuote').onclick=()=>{db.tasks.unshift({id:uid('task'),title:`Prepare quotation for ${route($('rcRoute').value)}`,ownerRole:'Finance',linkedType:'route',linkedId:$('rcRoute').value,due:today(),priority:'Normal',status:'Open'});commit('Quotation task created')}}const ss=$('saveSettings');if(ss)ss.onclick=()=>{db.settings.dieselPrice=num($('setDiesel').value);db.settings.vat=num($('setVat').value);db.settings.targetKml=num($('setKml').value);db.settings.standingFee=num($('setStanding').value);commit('Operating defaults updated')};const sd=$('saveDriver');if(sd)sd.onclick=()=>{db.settings.currentDriver=$('setDriver').value;commit('Driver identity updated')};if($('downloadBackup'))$('downloadBackup').onclick=backup;if($('restoreBackup'))$('restoreBackup').onclick=()=>{$('fileInput').dataset.kind='restore';$('fileInput').click()};if($('resetData'))$('resetData').onclick=()=>{if(confirm('Reset all demonstration data?')){db=structuredClone(base);commit('Demonstration data reset')}}}
$('menuBtn').onclick=()=>$('sidebar').classList.toggle('open');$('closeModal').onclick=()=>$('modal').classList.add('hidden');$('entryForm').onsubmit=saveForm;$('quickTripBtn').onclick=()=>openForm('trip');$('backupBtn').onclick=backup;$('roleSelect').onchange=e=>{role=e.target.value;localStorage.setItem('angermund_role',role);page=role==='driver'?'driverPortal':'command';render()};$('fileInput').onchange=()=>{if($('fileInput').files[0]&&$('fileInput').dataset.kind==='restore')restore($('fileInput').files[0]);$('fileInput').value=''};window.onclick=e=>{if(e.target===$('modal'))$('modal').classList.add('hidden')};if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js');localStorage.setItem(STORE,JSON.stringify(db));render();
